from more_itertools import numeric_range
from fractions import Fraction
from decimal import Decimal,localcontext
from itertools import islice
import subprocess
ns={'__name__':'more_itertools._review_old','__package__':'more_itertools'}
exec(subprocess.check_output(['git','show','6a1d360604c4e5dca0519dc7146e3c84ffeef239:more_itertools/more.py']),ns)
Old=ns['numeric_range']
for args in [(2**53+1,2**53, -1.0), (-(2**53+1),-(2**53),1.0),(2**53+1,2**53+1,1.0),(0.0,1.0,float('inf')),(1.0,0.0,-float('inf'))]:
 r=numeric_range(*args)
 print(args, 'iter',list(islice(iter(r),5)), 'len',len(r),'bool',bool(r))
for p in (1,2,4,28):
 for start in ('0','1','-1','1E100','1E-100'):
  for stop in ('-2','0','2','1E101'):
   for step in ('-0.1','0.1','1','1E-100'):
    for v in ('0','0.01','0.1','1','1E100'):
     args=tuple(map(Decimal,(start,stop,step))); value=Decimal(v)
     outcomes=[]
     for C in (Old,numeric_range):
      with localcontext() as c:
       c.prec=p
       for k in c.traps:c.traps[k]=True
       try:
        r=C(*args); result=value in r
        outcome=('ok',result,tuple(k.__name__ for k,on in c.flags.items() if on))
       except Exception as e:outcome=(type(e).__name__,tuple(k.__name__ for k,on in c.flags.items() if on))
       outcomes.append(outcome)
     if outcomes[0]!=outcomes[1]:print('DELTA',p,args,value,outcomes)
print('done')
PY

