from more_itertools import numeric_range
from fractions import Fraction
from itertools import islice
import math
s=Fraction(1,10**325)
for args in [(0.0,5e-324,s),(0.0,-5e-324,-s)]:
 r=numeric_range(*args)
 a=list(iter(r))
 print('fraction-underflow',args[0:2], 'count',len(a),'unique',set(a))
 for label,call in [('len',lambda:len(r)),('contains',lambda:a[0] in r),('index',lambda:r.index(a[0]))]:
  try: print(label,call())
  except Exception as e: print(label,type(e).__name__,str(e))
# Bounded independent oracle: compare only naturally terminating small ranges.
cases=0
for start in [0,0.,Fraction(0),2**53+1,-2**53-1,Fraction(2**53+1),1e308,-1e308]:
 for step in [1.,-1.,.1,-.1,1e308,-1e308,Fraction(1,10),Fraction(-1,10),2,-2]:
  for stop in [0,1.,-1.,2**53+11,-2**53-11,1e308,-1e308]:
   r=numeric_range(start,stop,step)
   try:
    a=list(islice(iter(r),64))
   except (OverflowError,TypeError):
    continue
   if len(a)==64: continue
   assert len(r)==len(a),(start,stop,step,'length',len(r),a)
   for i,v in enumerate(a):
    assert v in r,(start,stop,step,'contains',v)
    assert r.index(v)==a.index(v),(start,stop,step,'index',v)
   cases+=1
print('bounded matrix passed',cases)
PY

